def count_letters(text):
    counts = {}
    for ch in text:
        if ch.isalpha():
            letter = ch.lower()
            counts[letter] = counts.get(letter, 0) + 1
    return counts

def describe_temp(celsius):
    if celsius > 30:
        return "hot"
    elif celsius >= 20:
        return "warm"
    elif celsius >= 10:
        return "cool"
    else:
        return "cold"

def fizzbuzz(n):
    if n % 3 == 0 and n % 5 == 0:
        return "fizzbuzz"
    elif n % 3 == 0:
        return "fizz"
    elif n % 5 == 0:
        return "buzz"
    else:
        return str(n)

def password_strength(password):
    if len(password) < 6:
        return "weak"
    elif len(password) < 10:
        return "ok"
    else:
        return "strong"

